window.products.push({"id":1076925,"name":"Italian Blessing Ornament","category":"homeandappliances","retail price":15.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61N+vnW8PmL._AC_SL1000_.jpg","description":"Our quality Italian Blessing Ornament measures approx. 3.5\" and is made from Imported European blown glass. Italian Blessing Ornament: On one side it says: Lord, we ask you to help us make this house a home where its foundation is built upon the Lord... Where its rooms are warm with years of laughter, dreams and family memories... On the other side of the Italian Blessing ornament it says in English Where its windows look out upon the world and reflect the beauty and blessings near at hand... Where its doors are open wide and welcome those who would share the love that lives here.","images":["https://m.media-amazon.com/images/I/61N+vnW8PmL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Express Design Group","source_asin":"B01G1FG6ZU","category_path":"Home & Kitchen"},"sku":"BM-1076925","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01G1FG6ZU","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01G1FG6ZU","price_pending":true,"merchant_ready":false});
